const http = require('node:http');
const crypto = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');

const DEFAULT_TIMEOUT_MS = 2000;

function expandEnv(value, env) {
  return String(value).replace(/\$\{([^}]+)\}/g, (_, name) => {
    if (!(name in env)) {
      throw new Error(`routes config references missing env var '${name}'`);
    }
    return env[name];
  });
}

class TokenBucket {
  constructor({ capacity, refillPerSecond }) {
    if (!(capacity >= 1)) throw new Error('rateLimit.capacity must be >= 1');
    if (!(refillPerSecond >= 0)) throw new Error('rateLimit.refillPerSecond must be >= 0');
    this.capacity = capacity;
    this.refillPerSecond = refillPerSecond;
    this.tokens = capacity;
    this.lastRefill = process.hrtime.bigint();
  }

  /** @returns {{ ok: boolean, retryAfterSeconds?: number }} */
  tryTake() {
    const now = process.hrtime.bigint();
    const elapsedSeconds = Number(now - this.lastRefill) / 1e9;
    this.lastRefill = now;
    this.tokens = Math.min(this.capacity, this.tokens + elapsedSeconds * this.refillPerSecond);
    if (this.tokens >= 1) {
      this.tokens -= 1;
      return { ok: true };
    }
    const deficit = 1 - this.tokens;
    const retryAfterSeconds = this.refillPerSecond > 0 ? Math.ceil(deficit / this.refillPerSecond) : 60;
    return { ok: false, retryAfterSeconds };
  }
}

function compileRoute(route, env) {
  const { prefix } = route;
  if (!prefix || !prefix.startsWith('/')) {
    throw new Error(`route has invalid prefix: ${JSON.stringify(prefix)}`);
  }
  return {
    prefix,
    rewrite: route.rewrite == null ? '' : String(route.rewrite),
    target: new URL(expandEnv(route.target, env)),
    bucket: route.rateLimit ? new TokenBucket(route.rateLimit) : null,
  };
}

function loadConfig(file, env = process.env) {
  const raw = JSON.parse(fs.readFileSync(file, 'utf8'));
  raw.routes.sort((a, b) => b.prefix.length - a.prefix.length); // longest prefix wins
  return {
    timeoutMs: raw.upstreamTimeoutMs ?? DEFAULT_TIMEOUT_MS,
    port: raw.port ?? 0,
    routes: raw.routes.map((r) => compileRoute(r, env)),
