function createGateway(config) {
  function sendJson(res, status, payload, extraHeaders = {}) {
    if (res.writableEnded || res.writableEnded === false && res.headersSent) return;
    const body = JSON.stringify(payload);
    res.writeHead(status, {
      'content-type': 'application/json',
      'content-length': Buffer.byteLength(body),
      ...extraHeaders,
    });
    res.end(body);
  }

  function forward(req, res, route, bufferedBody, attempt) {
    let targetPath = route.rewrite + req.url.slice(route.prefix.length);
    if (targetPath === '') targetPath = '/';

    // Header propagation: append client IP to X-Forwarded-For, keep or mint X-Request-ID.
    const headers = { ...req.headers };
    const clientIp = normalizeIp(req.socket.remoteAddress);
    headers['x-forwarded-for'] = headers['x-forwarded-for']
      ? `${headers['x-forwarded-for']}, ${clientIp}`
      : clientIp;
    if (!headers['x-request-id']) headers['x-request-id'] = crypto.randomUUID();
    headers.host = route.target.host;

    let timedOut = false;
    const upstream = http.request(
      {
        protocol: route.target.protocol,
        hostname: route.target.hostname,
        port: route.target.port,
        method: req.method,
        path: targetPath,
        headers,
        agent: false,
      },
      (uRes) => {
        const status = uRes.statusCode;
        if (attempt === 0 && req.method === 'GET' && (status === 502 || status === 503)) {
          uRes.resume(); // drain and discard the failed attempt
          uRes.on('end', () => forward(req, res, route, bufferedBody, attempt + 1));
          uRes.on('error', () => {});
          return;
        }
        res.writeHead(status, uRes.headers);
        uRes.pipe(res);
      },
    );

    upstream.setTimeout(config.timeoutMs, () => {
      timedOut = true;
      upstream.destroy(new Error(`upstream timeout after ${config.timeoutMs}ms`));
    });

    upstream.on('error', () => {
      if (res.writableEnded) return;
      if (timedOut) {
        sendJson(res, 504, {
          error: 'gateway_timeout',
          message: `upstream did not respond within ${config.timeoutMs}ms`,
        }, { 'x-gateway-timeout': String(config.timeoutMs) });
      } else {
        sendJson(res, 502, { error: 'bad_gateway', message: 'upstream request failed' });
      }
    });

    if (bufferedBody.length > 0) upstream.write(bufferedBody);
    upstream.end();
  }

  const server = http.createServer((req, res) => {
    if (req.url === '/healthz') {
      sendJson(res, 200, { status: 'ok' });
      return;
    }

    const route = config.routes.find(
      (r) => req.url === r.prefix || req.url.startsWith(`${r.prefix}/`),
    );
    if (!route) {
      sendJson(res, 404, { error: 'not_found', message: `no route matches ${req.url}` });
      return;
    }

    if (route.bucket) {
      const verdict = route.bucket.tryTake();
      if (!verdict.ok) {
        sendJson(res, 429, { error: 'rate_limited', message: 'token bucket exhausted for this route' }, {
          'retry-after': String(verdict.retryAfterSeconds),
        });
        return;
      }
    }

    const chunks = [];
    req.on('data', (c) => chunks.push(c));
    req.on('error', () => res.destroy());
    req.on('end', () => forward(req, res, route, Buffer.concat(chunks), 0));
  });

  return server;
}

function main() {
  const configFile =
    process.argv[2] ||
    process.env.GATEWAY_CONFIG ||
    path.join(process.cwd(), 'routes.json');
  const config = loadConfig(configFile);
  const port = Number(process.env.PORT ?? config.port ?? 0);
  const server = createGateway(config);
  server.listen(port, '127.0.0.1', () => {
    const { address, port: boundPort } = server.address();
    console.log(`[gateway] listening on http://${address}:${boundPort}`);
  });
}

module.exports = { createGateway, loadConfig, TokenBucket };

if (require.main === module) main();
