/**
 * Integration tests: boot users-svc, orders-svc and the gateway on random
 * ports and cover every gateway feature:
 *
 *   1. prefix routing to both backends
 *   2. path rewrite (prefix stripped / replaced)
 *   3. per-route token-bucket rate limiting (429 + Retry-After)
 *   4. GET retried exactly once on upstream 503 -> succeeds, backend saw 2 calls
 *   5. POST never retried on 503 -> client sees 503, backend saw exactly 1 call
 *   6. upstream timeout -> 504 within ~2s
 *   7. X-Forwarded-For append + X-Request-ID propagation/generation
 *   8. unknown prefix -> 404
 */

const { test, before, after } = require('node:test');
const assert = require('node:assert/strict');
const { spawn } = require('node:child_process');
const net = require('node:net');
const path = require('node:path');
const crypto = require('node:crypto');

const ROOT = path.resolve(__dirname, '..');

let usersPort;
let ordersPort;
let gatewayPort;
let gatewayBase;
let children = [];

function freePort() {
  return new Promise((resolve, reject) => {
    const srv = net.createServer();
    srv.listen(0, '127.0.0.1', () => {
      const port = srv.address().port;
      srv.close(() => resolve(port));
    });
    srv.on('error', reject);
  });
}

function startService(script, port) {
  const child = spawn(process.execPath, [script], {
    cwd: ROOT,
    env: { ...process.env, PORT: String(port) },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  child.stderr.on('data', () => {}); // keep pipes drained
  children.push(child);
  return child;
}

async function waitForReady(url, label, deadlineMs = 15000) {
  const deadline = Date.now() + deadlineMs;
  while (Date.now() < deadline) {
    try {
      const res = await fetch(url);
      if (res.ok) return;
    } catch {
      /* not up yet */
    }
    await sleep(100);
  }
  throw new Error(`${label} did not become ready at ${url}`);
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function call(method, urlPath, { headers = {}, body } = {}) {
  const res = await fetch(`${gatewayBase}${urlPath}`, {
    method,
    headers,
    body,
    redirect: 'manual',
  });
  const text = await res.text();
  let json = null;
  try {
    json = JSON.parse(text);
  } catch {
    /* non-JSON body */
  }
  return { status: res.status, headers: res.headers, json, text };
}

before(async () => {
  usersPort = await freePort();
  ordersPort = await freePort();
  gatewayPort = await freePort();

  startService(path.join(ROOT, 'services/users-svc.js'), usersPort);
  startService(path.join(ROOT, 'services/orders-svc.js'), ordersPort);

  const gatewayChild = spawn(
    process.execPath,
    ['gateway.js', path.join(ROOT, 'routes.json')],
    {
      cwd: ROOT,
      env: {
        ...process.env,
        PORT: String(gatewayPort),
        USERS_SVC_URL: `http://127.0.0.1:${usersPort}`,
        ORDERS_SVC_URL: `http://127.0.0.1:${ordersPort}`,
      },
      stdio: ['ignore', 'pipe', 'pipe'],
    },
  );
  gatewayChild.stderr.on('data', () => {});
  children.push(gatewayChild);

  await waitForReady(`http://127.0.0.1:${usersPort}/healthz`, 'users-svc');
  await waitForReady(`http://127.0.0.1:${ordersPort}/healthz`, 'orders-svc');
  gatewayBase = `http://127.0.0.1:${gatewayPort}`;
  await waitForReady(`${gatewayBase}/healthz`, 'gateway');
});

after(() => {
  for (const child of children) {
    child.kill('SIGTERM');
  }
});

test('routes by prefix to the matching backend', async () => {
  const users = await call('GET', '/users/ping');
  assert.equal(users.status, 200);
  assert.equal(users.json.service, 'users');
  assert.equal(users.json.path, '/ping');

  const orders = await call('GET', '/orders/ping');
  assert.equal(orders.status, 200);
  assert.equal(orders.json.service, 'orders');
  assert.equal(orders.json.path, '/ping');
});

test('rewrites the path when proxying', async () => {
  // /api/orders/ping -> rewrite "" strips the matched prefix entirely.
  const stripped = await call('GET', '/api/orders/ping?x=1');
  assert.equal(stripped.status, 200);
  assert.equal(stripped.json.service, 'orders');
  assert.equal(stripped.json.path, '/ping'); // rewritten, query preserved

  // /limited/* -> rewrite "/orders" replaces the prefix; longest-prefix wins
  // over plain "/orders" only for longer matches, so use a distinct subpath.
  const replaced = await call('GET', '/limited/counts/nothing-here');
  assert.equal(replaced.json.service, 'orders');
  assert.equal(replaced.json.path, '/orders/counts/nothing-here');
});

test('POST bodies survive proxying through a rewrite route', async () => {
  const payload = JSON.stringify({ item: 'sku-42', qty: 2 });
  const res = await fetch(`${gatewayBase}/api/orders/echo`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: payload,
  });
  assert.equal(res.status, 200);
  const json = await res.json();
  assert.equal(json.service, 'orders');
  assert.deepEqual(JSON.parse(json.body), { item: 'sku-42', qty: 2 });
});

test('retries an idempotent GET once on 503 and succeeds', async () => {
  const requestId = crypto.randomUUID();
  const first = await call('GET', '/users/flaky', { headers: { 'x-request-id': requestId } });
  assert.equal(first.status, 200); // gateway swallowed the 503 via retry
  assert.ok(first.json.invocations >= 2);

  const counts = await call('GET', `/users/counts/${requestId}`);
  assert.equal(counts.json.invocations, 2); // exactly one retry, not two
});

test('never retries a POST on 503 (backend counts invocations)', async () => {
  const requestId = crypto.randomUUID();
  const res = await call('POST', '/orders/flaky', {
    headers: { 'x-request-id': requestId },
    body: '{"order":1}',
  });
  assert.equal(res.status, 503); // the single upstream failure is passed through
  assert.equal(res.json.invocations, 1);

  const counts = await call('GET', `/orders/counts/${requestId}`);
  assert.equal(counts.json.invocations, 1); // proof: POST was sent exactly once
});

test('returns 504 when the upstream exceeds the 2s timeout', async () => {
  const startedAt = Date.now();
  const res = await call('GET', '/users/slow'); // backend sleeps 3000ms
  const elapsed = Date.now() - startedAt;

  assert.equal(res.status, 504);
  assert.equal(res.json.error, 'gateway_timeout');
  assert.equal(res.headers.get('x-gateway-timeout'), '2000');
  assert.ok(elapsed >= 1900, `gateway gave up too early (${elapsed}ms)`);
  assert.ok(elapsed < 2900, `gateway cut off too late (${elapsed}ms), expected ~2000ms`);
});

test('propagates X-Forwarded-For and X-Request-ID from the client', async () => {
  const requestId = crypto.randomUUID();
  const res = await call('GET', '/users/ping', {
    headers: { 'x-request-id': requestId, 'x-forwarded-for': '10.0.0.1, 10.0.0.2' },
  });

  assert.equal(res.status, 200);
  assert.equal(res.json.headers['x-request-id'], requestId);
  assert.match(res.json.headers['x-forwarded-for'], /^10\.0\.0\.1, 10\.0\.0\.2,/);
  assert.ok(res.json.headers['x-forwarded-for'].endsWith('127.0.0.1'));
});

test('mints an X-Request-ID and seeds X-Forwarded-For when absent', async () => {
  const res = await call('GET', '/orders/ping');
  assert.equal(res.status, 200);

  const requestId = res.json.headers['x-request-id'];
  assert.ok(requestId && /^[0-9a-f-]{36}$/.test(requestId), `got ${requestId}`);

  assert.equal(res.json.headers['x-forwarded-for'], '127.0.0.1');
});

test('enforces the per-route token-bucket rate limit with 429 + Retry-After', async () => {
  // Route /limited has capacity 3 and negligible refill in this config.
  const statuses = [];
  let retryAfter = null;
  for (let i = 0; i < 5; i++) {
    const res = await call('GET', '/limited/ping');
    statuses.push(res.status);
    if (res.status === 429) {
      retryAfter = res.headers.get('retry-after');
      assert.equal(res.json.error, 'rate_limited');
    }
  }
  assert.deepEqual(statuses.slice(0, 3), [200, 200, 200]);
  assert.equal(statuses[3], 429);
  assert.equal(statuses[4], 429);
  assert.ok(Number(retryAfter) > 0, `expected a positive Retry-After, got ${retryAfter}`);
});

test('other routes are unaffected while /limited is exhausted', async () => {
  const res = await call('GET', '/users/ping');
  assert.equal(res.status, 200);
});

test('returns 404 for unknown prefixes', async () => {
  const res = await call('GET', '/nope/deeper');
  assert.equal(res.status, 404);
  assert.equal(res.json.error, 'not_found');
});
